cssCode:
.planet {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: linear-gradient(145deg, #ff7e5f, #feb47b);
  box-shadow: inset -20px -20px 30px rgba(0,0,0,0.6), 0 0 20px #ff7e5f;
  position: relative;
  transition: transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.planet-ring {
  position: absolute;
  width: 200px; 
  height: 60px;
  border: 4px solid rgba(255, 255, 255, 0.4);
  border-radius: 50%;
  transform: rotateX(70deg) rotateY(15deg);
  transition: width 0.6s ease, height 0.6s ease, border-color 0.6s ease, box-shadow 0.6s ease;
}

/* ગ્રહ પર ટચ કે હોવર કરવાથી થતો ફેરફાર */
.planet:hover, .planet:active {
  transform: scale(1.3) rotate(20deg);
  box-shadow: inset -20px -20px 30px rgba(0,0,0,0.6), 0 0 50px #ff7e5f;
}

.planet:hover .planet-ring, .planet:active .planet-ring {
  width: 250px;
  height: 80px;
  border-color: #00ffcc;
  box-shadow: 0 0 30px #00ffcc, inset 0 0 15px #00ffcc;
}

